.editor-help { margin: var(--g-spacing-3) 0 0; max-width: 700px; }
.form-actions { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-5); margin-top: var(--g-spacing-7); padding-top: var(--g-spacing-6); border-top: 1px solid var(--g-color-line-generic); }
.form-actions > button { flex-shrink: 0; }
